namespace aether {
bool validTerminalImage(std::string_view s){
 if(s.empty())return true;if(s.size()>4096||s.find_first_of("\r\n\t\"")!=s.npos)return false;
 // Data only; drive-absolute local paths. The worker also rejects remote paths.
 if(s.size()<4||!std::isalpha(static_cast<unsigned char>(s[0]))||s[1]!=':'||(s[2]!='\\'&&s[2]!='/'))return false;
 auto dot=s.find_last_of('.');if(dot==s.npos)return false;auto ext=std::string(s.substr(dot));std::transform(ext.begin(),ext.end(),ext.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return ext==".png"||ext==".jpg"||ext==".jpeg";
}
Theme terminalDesignTheme(const Theme& source,int design){
 if(design<1||design>10)return source;
 struct Colors{std::uint32_t bg,fg,accent,muted;};
 constexpr Colors colors[]={
  {0x2B1027,0xF5E9EE,0xF39765,0xC9A8BE},{0x20202C,0xF0ECFF,0xC2A1FF,0xA4A2BB},
  {0x252E3B,0xE4EDF5,0x8BC8D7,0xA4B6CA},{0x211F30,0xE5DDF6,0xD7B6F2,0xAEA5C3},
  {0x171E32,0xD6E3FA,0x80B7F4,0x9BAFCE},{0x2B2824,0xF0E1C3,0xD7B36B,0xC5B794},
  {0xF5EEDC,0x334B55,0x246B7A,0x586D73},{0x171B21,0xDFE6EE,0x75B8E8,0x9BA9BA},
  {0x10251D,0xE2F0DA,0x9ACB91,0xA6BCAA},{0x21162D,0xF8E6FF,0xEB92DD,0xC4A1D3}};
 const auto c=colors[design-1];auto t=source;t.name=std::string(TerminalDesignNames[design]);t.background=c.bg;t.foreground=c.fg;t.accent=c.accent;t.muted=c.muted;
 auto mix=[](std::uint32_t a,std::uint32_t b){return ((a&0xFEFEFE)>>1)+((b&0xFEFEFE)>>1);};
 t.surface=mix(c.bg,mix(c.bg,c.muted));t.raised=mix(t.surface,c.muted);return t;
}
bool darkTheme(const Theme& t){return (((t.background>>16)&255)*299+((t.background>>8)&255)*587+(t.background&255)*114)<128000;}
namespace {bool ruleName(std::string_view s){return !s.empty()&&s.size()<=128&&s.find_first_of("/\\\r\n\t\"")==s.npos&&s.ends_with(".exe");}}
IntegrationOptions parseIntegration(std::string_view text){IntegrationOptions o;if(text.size()>65536)return o;std::istringstream in{std::string(text)};std::string line;if(!std::getline(in,line))return o;if(!line.empty()&&line.back()=='\r')line.pop_back();if(line!="AetherIntegration1")return o;while(std::getline(in,line)){std::istringstream row(line);std::string key,value;int n=0;if(!(row>>key))continue;if(key=="rule"){if(row>>std::quoted(value)>>n&&ruleName(value)&&n>=0&&n<=3&&o.rules.size()<64){std::transform(value.begin(),value.end(),value.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});auto i=std::find_if(o.rules.begin(),o.rules.end(),[&](const auto& v){return v.executable==value;});if(i==o.rules.end())o.rules.push_back({value,static_cast<FrameMode>(n)});}continue;}if(key=="image"){if(row>>std::quoted(value)&&validTerminalImage(value))o.terminalImage=value;continue;}if(key=="font"){if(row>>std::quoted(value)&&validFontFamily(value))o.terminalFont=value;continue;}if(!(row>>n))continue;if(key=="windowsMode")o.windowsMode=n==1;else if(key=="windowsAccent")o.windowsAccent=n==1;else if(key=="frames")o.frames=n==1;else if(key=="terminal")o.terminal=n==1;else if(key=="restoreOnExit")o.restoreOnExit=n!=0;else if(key=="size")o.terminalSize=std::clamp(n,10,24);else if(key=="opacity")o.terminalOpacity=std::clamp(n,50,100);else if(key=="background")o.terminalBackground=n==1;else if(key=="design")o.terminalDesign=std::clamp(n,0,10);else if(key=="cursor")o.terminalCursor=std::clamp(n,0,2);else if(key=="shell")o.terminalShell=std::clamp(n,0,2);}return o;}
std::string serializeIntegration(const IntegrationOptions& o){std::ostringstream s;s<<"AetherIntegration1\nwindowsMode "<<o.windowsMode<<"\nwindowsAccent "<<o.windowsAccent<<"\nframes "<<o.frames<<"\nterminal "<<o.terminal<<"\nrestoreOnExit "<<o.restoreOnExit<<"\nfont "<<std::quoted(validFontFamily(o.terminalFont)?o.terminalFont:"Cascadia Mono")<<"\nsize "<<std::clamp(o.terminalSize,10,24)<<"\nopacity "<<std::clamp(o.terminalOpacity,50,100)<<"\nbackground "<<o.terminalBackground<<'\n';s<<"design "<<std::clamp(o.terminalDesign,0,10)<<"\ncursor "<<std::clamp(o.terminalCursor,0,2)<<"\nshell "<<std::clamp(o.terminalShell,0,2)<<"\nimage "<<std::quoted(validTerminalImage(o.terminalImage)?o.terminalImage:"")<<'\n';for(const auto& v:o.rules)if(ruleName(v.executable))s<<"rule "<<std::quoted(v.executable)<<' '<<static_cast<int>(v.mode)<<'\n';return s.str();}
std::string jsonString(std::string_view v){std::ostringstream s;s<<'"';for(unsigned char c:v){if(c=='"'||c=='\\')s<<'\\'<<static_cast<char>(c);else if(c<32)s<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<static_cast<int>(c)<<std::dec;else s<<static_cast<char>(c);}s<<'"';return s.str();}
std::array<std::uint32_t,16> terminalPalette(const Theme& t){if(!darkTheme(t))return {0x20242D,0xA52B38,0x286638,0x785800,0x265DA2,0x704095,0x14686C,0x3F4651,0x565E6C,0xB62A3A,0x36723A,0x795C00,0x2B63AD,0x805096,0x167078,0x181C24};return {t.background,0xD75F67,0x85B97C,0xD5BA78,0x729ED9,0xB58ED3,0x65BDBB,t.foreground,t.muted,0xF28B82,0xACD49E,0xF4DA98,0xA5C8FA,0xD4B1ED,t.accent,0xFFFFFF};}
std::string terminalFragment(const Theme& source,const IntegrationOptions& o,std::string_view wd,std::string_view image){const auto t=terminalDesignTheme(source,o.terminalDesign);auto rgb=[](std::uint32_t c){std::ostringstream v;v<<'"'<<'#'<<std::hex<<std::uppercase<<std::setw(6)<<std::setfill('0')<<(c&0xFFFFFF)<<'"';return v.str();};auto palette=terminalPalette(t);const char* names[]={"black","red","green","yellow","blue","purple","cyan","white","brightBlack","brightRed","brightGreen","brightYellow","brightBlue","brightPurple","brightCyan","brightWhite"};std::ostringstream s;s<<"{\"schemes\":[{\"name\":\"Aether\",\"background\":"<<rgb(t.background)<<",\"foreground\":"<<rgb(t.foreground)<<",\"cursorColor\":"<<rgb(t.accent)<<",\"selectionBackground\":"<<rgb(t.raised);for(int n=0;n<16;++n)s<<','<<jsonString(names[n])<<':'<<rgb(palette[n]);s<<"}],\"profiles\":[";const char* labels[]={"PowerShell","Command Prompt","WSL"};const char* guids[]={"{67f59045-6691-4bf0-9dc4-ae7eae000001}","{67f59045-6691-4bf0-9dc4-ae7eae000002}","{67f59045-6691-4bf0-9dc4-ae7eae000003}"};for(int n=0;n<3;++n){if(n)s<<',';std::string command='"'+std::string(wd)+(n==0?"\\System32\\WindowsPowerShell\\v1.0\\powershell.exe":n==1?"\\System32\\cmd.exe":"\\System32\\wsl.exe")+'"';if(n==0)command+=" -NoLogo";s<<"{\"guid\":"<<jsonString(guids[n])<<",\"name\":"<<jsonString(std::string("Aether ")+labels[n])<<",\"commandline\":"<<jsonString(command)<<",\"startingDirectory\":\"%USERPROFILE%\",\"colorScheme\":\"Aether\",\"font\":{\"face\":"<<jsonString(o.terminalFont)<<",\"size\":"<<o.terminalSize<<"},\"cursorShape\":\"filledBox\",\"useAcrylic\":true,\"opacity\":"<<o.terminalOpacity;if(o.terminalBackground&&!image.empty())s<<",\"backgroundImage\":"<<jsonString(image)<<",\"backgroundImageOpacity\":0.15";s<<'}';}s<<"]}";return s.str();}
}
